// i18n helper for the giveowl.com pages. English is the text in the HTML; other languages load on demand
// from assets/lang/<code>.js (generated by scripts/bygg-i18n.mjs from i18n/web/ and i18n/privacy/).
// Picks ?lang=, then the page language (data-sidesprak on translated landing pages), then the saved choice,
// then the browser language, then English. On landing pages the picker navigates to /<lang>/.
(function(){
  var SPRAK=[{"code":"en","navn":"English","locale":"en-US","dir":"ltr"},{"code":"nb","navn":"Norsk (bokmål)","locale":"nb-NO","dir":"ltr"},{"code":"es","navn":"Español","locale":"es-ES","dir":"ltr"},{"code":"pt-BR","navn":"Português (Brasil)","locale":"pt-BR","dir":"ltr"},{"code":"fr","navn":"Français","locale":"fr-FR","dir":"ltr"},{"code":"de","navn":"Deutsch","locale":"de-DE","dir":"ltr"},{"code":"it","navn":"Italiano","locale":"it-IT","dir":"ltr"},{"code":"nl","navn":"Nederlands","locale":"nl-NL","dir":"ltr"},{"code":"pl","navn":"Polski","locale":"pl-PL","dir":"ltr"},{"code":"sv","navn":"Svenska","locale":"sv-SE","dir":"ltr"},{"code":"da","navn":"Dansk","locale":"da-DK","dir":"ltr"},{"code":"fi","navn":"Suomi","locale":"fi-FI","dir":"ltr"},{"code":"tr","navn":"Türkçe","locale":"tr-TR","dir":"ltr"},{"code":"ja","navn":"日本語","locale":"ja-JP","dir":"ltr"},{"code":"ko","navn":"한국어","locale":"ko-KR","dir":"ltr"},{"code":"zh-Hans","navn":"简体中文","locale":"zh-CN","dir":"ltr"},{"code":"hi","navn":"हिन्दी","locale":"hi-IN","dir":"ltr"},{"code":"id","navn":"Bahasa Indonesia","locale":"id-ID","dir":"ltr"},{"code":"ar","navn":"العربية","locale":"ar-u-nu-latn","dir":"rtl"}];
  function info(c){for(var i=0;i<SPRAK.length;i++) if(SPRAK[i].code===c) return SPRAK[i]; return null;}
  function norm(x){x=String(x||'').replace('_','-'); var p=x.split('-')[0].toLowerCase();
    if(/^(nb|nn|no)$/.test(p)) return 'nb'; if(p==='pt') return 'pt-BR'; if(p==='zh') return 'zh-Hans'; if(p==='in') return 'id';
    if(info(x)) return x; return info(p)?p:null;}
  function hent(){try{return JSON.parse(localStorage.getItem('giveowl.lang'));}catch(e){return null;}}
  function lagre(v){try{localStorage.setItem('giveowl.lang',JSON.stringify(v));}catch(e){}}
  var q=new URLSearchParams(location.search);
  var l=(navigator.languages&&navigator.languages.length?navigator.languages:[navigator.language||'en']);
  var enhet='en'; for(var i=0;i<l.length;i++){var s=norm(l[i]); if(s){enhet=s;break;}}
  var side=document.documentElement.getAttribute('data-sidesprak');
  var lang=norm(q.get('lang'))||(side&&norm(side))||norm(hent())||enhet;
  function sideUrl(c){return '/'+(c==='en'?'':c.toLowerCase()+'/');}
  var me=document.currentScript&&document.currentScript.src; var BASE=me?me.replace(/i18n\.js(\?.*)?$/,''):'assets/';
  var lastet={};
  function last(c,cb){ if(c==='en'||(window.GO_WEB&&window.GO_WEB[c])) return cb();
    if(lastet[c]) return lastet[c].push(cb); lastet[c]=[cb];
    var s=document.createElement('script'); s.src=BASE+'lang/'+c+'.js';
    s.onload=s.onerror=function(){var a=lastet[c]; lastet[c]=null; a.forEach(function(f){f();});}; document.head.appendChild(s);}
  window.GiveOwlI18n=function(page){
    function T(){var w=(window.GO_WEB||{})[lang]||{}; var o={}; var f=w.felles||{}, p=w[page]||{}; for(var k in f) o[k]=f[k]; for(var k2 in p) o[k2]=p[k2]; return o;}
    function tegn(){
      var t=lang==='en'?{}:T(); var si=info(lang)||{dir:'ltr'};
      document.documentElement.lang=lang; document.documentElement.dir=si.dir||'ltr';
      document.querySelectorAll('[data-t]').forEach(function(n){if(n.dataset.en==null)n.dataset.en=n.innerHTML;var v=t[n.getAttribute('data-t')];n.innerHTML=v!=null?v:n.dataset.en;});
      document.querySelectorAll('[data-tp]').forEach(function(n){if(n.dataset.enp==null)n.dataset.enp=n.getAttribute('placeholder')||'';var v=t[n.getAttribute('data-tp')];n.setAttribute('placeholder',v||n.dataset.enp);});
      if(window.__enTitle==null)window.__enTitle=document.title; document.title=t._title||window.__enTitle;
      var sel=document.getElementById('sprak'); if(sel){sel.value=lang; sel.setAttribute('aria-label',t._sprak||'Language');}
      window.GiveOwlT=function(k,en){return t[k]!=null?t[k]:en;};
      document.dispatchEvent(new CustomEvent('giveowl:lang',{detail:{lang:lang,t:t}}));
    }
    var sel=document.getElementById('sprak');
    if(sel){ sel.innerHTML=''; SPRAK.forEach(function(x){var o=document.createElement('option');o.value=x.code;o.textContent=x.navn;o.lang=x.code;sel.appendChild(o);});
      sel.onchange=function(){lang=sel.value;lagre(lang);
        // Landing pages have one static URL per language (for search engines): go there.
        if(side!==null||(page==='index'&&location.pathname==='/')){location.href=sideUrl(lang);return;}
        last(lang,tegn);}; }
    window.GiveOwlT=function(k,en){return en;};
    last(lang,tegn); return function(){return lang;};
  };
})();
